function canMouseWin(grid, catJump, mouseJump) {
  const rows = grid.length;
  const cols = grid[0].length;
  const cells = grid.join('');
  const size = cells.length;
  const food = cells.indexOf('F');
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];

  function jumps(cell, limit) {
    const targets = [cell];
    for (const [dr, dc] of directions) {
      for (let step = 1; step <= limit; step++) {
        const r = Math.floor(cell / cols) + dr * step;
        const c = (cell % cols) + dc * step;
        if (r < 0 || r >= rows || c < 0 || c >= cols || cells[r * cols + c] === '#') break;
        targets.push(r * cols + c);
      }
    }
    return targets;
  }

  const mouseMoves = Array.from({ length: size }, (_, cell) => jumps(cell, mouseJump));
  const catMoves = Array.from({ length: size }, (_, cell) => jumps(cell, catJump));
  const MOUSE_WIN = 1;
  const CAT_WIN = 2;
  const result = new Array(size * size * 2).fill(0);
  const degree = new Array(size * size * 2).fill(0);
  const queue = [];

  for (let mouse = 0; mouse < size; mouse++) {
    for (let cat = 0; cat < size; cat++) {
      if (cells[mouse] === '#' || cells[cat] === '#') continue;
      const state = (mouse * size + cat) * 2;
      degree[state] = mouseMoves[mouse].length;
      degree[state + 1] = catMoves[cat].length;
      let winner = 0;
      if (mouse === cat || cat === food) {
        winner = CAT_WIN;
      } else if (mouse === food) {
        winner = MOUSE_WIN;
      }
      for (let turn = 0; winner !== 0 && turn < 2; turn++) {
        result[state + turn] = winner;
        queue.push(state + turn);
      }
    }
  }

  for (let head = 0; head < queue.length; head++) {
    const state = queue[head];
    const mouse = Math.floor(state / (2 * size));
    const cat = Math.floor(state / 2) % size;
    const prevTurn = 1 - (state % 2);
    const moverWins = prevTurn === 0 ? MOUSE_WIN : CAT_WIN;
    const origins = prevTurn === 0 ? mouseMoves[mouse] : catMoves[cat];
    for (const from of origins) {
      const prev = prevTurn === 0 ? (from * size + cat) * 2 : (mouse * size + from) * 2 + 1;
      if (result[prev] !== 0) continue;
      degree[prev]--;
      if (result[state] === moverWins || degree[prev] === 0) {
        result[prev] = result[state];
        queue.push(prev);
      }
    }
  }
  return result[(cells.indexOf('M') * size + cells.indexOf('C')) * 2] === MOUSE_WIN;
}

