function canMouseWin(grid, catJump, mouseJump) {
  // Value iteration with an explicit turn count: after ply k, win[t] holds the states
  // from which the mouse can force a win within k moves (t = 0: mouse to move).
  const R = grid.length, C = grid[0].length, N = R * C;
  let mr = 0, mc = 0, cr = 0, cc = 0, fr = 0, fc = 0;
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) {
    if (grid[r][c] === 'M') { mr = r; mc = c; }
    if (grid[r][c] === 'C') { cr = r; cc = c; }
    if (grid[r][c] === 'F') { fr = r; fc = c; }
  }
  const open = (r, c) => r >= 0 && r < R && c >= 0 && c < C && grid[r][c] !== '#';
  const isFood = (r, c) => r === fr && c === fc;
  const id = (r, c) => r * C + c;
  const reach = (r, c, J) => {
    const out = [[r, c]];
    for (const [dr, dc] of [[0, 1], [1, 0], [0, -1], [-1, 0]]) {
      let nr = r, nc = c;
      for (let k = 0; k < J; k++) { nr += dr; nc += dc; if (!open(nr, nc)) break; out.push([nr, nc]); }
    }
    return out;
  };
  const free = [];
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) if (open(r, c)) free.push([r, c]);
  const mReach = new Map(), cReach = new Map();
  for (const [r, c] of free) { mReach.set(id(r, c), reach(r, c, mouseJump)); cReach.set(id(r, c), reach(r, c, catJump)); }
  let win = [new Uint8Array(N * N), new Uint8Array(N * N)];
  for (const [ar, ac] of free) for (const [br, bc] of free) {
    if ((ar !== br || ac !== bc) && isFood(ar, ac)) { win[0][id(ar, ac) * N + id(br, bc)] = 1; win[1][id(ar, ac) * N + id(br, bc)] = 1; }
  }
  for (let ply = 1; ply <= 1000; ply++) {
    const next = [win[0].slice(), win[1].slice()];
    let changed = false;
    for (const [ar, ac] of free) for (const [br, bc] of free) {
      const m = id(ar, ac), c = id(br, bc);
      if (m === c || isFood(br, bc) || isFood(ar, ac)) continue;
      if (!win[0][m * N + c] && mReach.get(m).some(([r, k]) => id(r, k) !== c && win[1][id(r, k) * N + c])) { next[0][m * N + c] = 1; changed = true; }
      if (!win[1][m * N + c] && cReach.get(c).every(([r, k]) => id(r, k) !== m && !isFood(r, k) && win[0][m * N + id(r, k)])) { next[1][m * N + c] = 1; changed = true; }
    }
    win = next;
    if (!changed) break;
  }
  return win[0][id(mr, mc) * N + id(cr, cc)] === 1;
}

