function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  let rows, cols;
  do {
    rows = large ? pick(6, 8) : pick(1, 4);
    cols = large ? pick(6, 8) : pick(1, 4);
  } while (rows * cols < 3);
  const wallRate = rand() * 0.4;
  const board = Array.from({ length: rows * cols }, () => (rand() < wallRate ? '#' : '.'));
  const spots = [];
  while (spots.length < 3) {
    const cell = pick(0, rows * cols - 1);
    if (!spots.includes(cell)) spots.push(cell);
  }
  board[spots[0]] = 'M';
  board[spots[1]] = 'C';
  board[spots[2]] = 'F';
  const grid = [];
  for (let r = 0; r < rows; r++) grid.push(board.slice(r * cols, (r + 1) * cols).join(''));
  const jumpMax = large ? 8 : 4;
  return [grid, pick(1, jumpMax), pick(1, jumpMax)];
}
